/*
	VIOC_player_utils.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "player_utils" (2026-10-18). Se compila en todas las maquinas desde init.sqf. La parte del cuerpo corre en el
	cliente del jugador (donde su unidad y su cuerpo son locales); la accion ELIMINAR VEHICULO se muestra en el cliente,
	pero la valida y la ejecuta el servidor (en la partida LAN el anfitrion es el servidor y la consola LOCAL EXEC llega a
	las dos partes). Sirve para las misiones A y B y para cualquier mapa; Oeste y Este.

	1) Tu cuerpo al reaparecer. Parametro de lobby VIOC_PU_BODY_DELETE: 0 = no (como el original), 1 = al momento,
	   30 = a los 30 s (por defecto), 120 = a los 120 s.
	   - Evento "Respawn" en la unidad del jugador (se pone una vez, en el cliente; los eventos puestos en el jugador donde es
	     local pasan a la unidad nueva al reaparecer, igual que el "killed" de BECTI en Client\Init\Init_Client.sqf y el
	     "Respawn" de BIS en Feedback\fn_feedbackInit.sqf). Su segundo argumento es el cuerpo. Solo jugadores humanos: la
	     IA no tiene este evento (el "respawn" de los jefes IA de BECTI esta en el servidor y no se toca).
	   - La mision usa respawn = 3 (BASE) con respawnDelay = 3 (Rsc\Game.hpp): el jugador reaparece en la base a los 3 s y
	     luego elige donde aparecer en el menu de BECTI; el cuerpo queda donde murio. "Al momento" = al reaparecer.
	   - El reloj empieza cuando termina el menu de reaparicion (CTI_P_Respawning vuelve a false; tope 300 s, por la rama de
	     la carcel que no lo pone en false), no al evento: el menu obliga a esperar CTI_RESPAWN_TIMER (20 s).
	   - El equipo: con CTI_RESPAWN_PENALTY = -1 ("Start with last Gear", el valor de la cadena de Tanoa)
	     Client_OnPlayerKilled.sqf copia el equipo del cuerpo en cti_gear_ondeath EN LA MUERTE y el menu lo pone desde esa
	     variable al reaparecer en la base, un campamento, una FOB o la ambulancia. PERO si reapareces en una IA de tu grupo
	     (CTI_RESPAWN_AI = 1 por defecto) recibes el equipo DE ESA IA y el tuyo solo queda en el cuerpo. Por eso, si al
	     terminar el menu tu uniforme, chaleco o mochila no son los del cuerpo, o desaparecio (se borro) una IA de tu grupo
	     (BECTI borra la IA en la que reapareces), o la penalizacion no es -1, la espera es al menos VIOC_PU_BODY_MIN_NOLAST
	     s (300, lo de antes del parche). Y nunca se borra mientras estes a menos de VIOC_PU_LOOT_R m (saqueandolo): se
	     reintenta cada 10 s, como mucho 30 veces.
	   - Al borrar: si el cuerpo esta dentro de un vehiculo se borra solo el cuerpo con deleteVehicleCrew (la wiki prohibe
	     deleteVehicle con tripulantes: asientos fantasma), ejecutado donde el vehiculo es local (remoteExecCall, como
	     VIOC_town_cleanup.sqf); el vehiculo no se toca. Si esta en el suelo, antes
	     se borran sus armas tiradas a 5 m (VIOC_PERF_fnc_bodyHolders de perf_cleanup: respeta su parametro y no las borra
	     con otro jugador a 50 m; sin perf_cleanup, lo mismo con WeaponHolderSimulated).
	   - Sin dobles borrados: la recogida de basura de BECTI (update_garbage_collector.fsm -> Server_TrashObject.sqf, que
	     duerme CTI_GC_DELAY_MAN = VIOC_PERF_CORPSE_TIME s) y el tope de cuerpos de perf_cleanup miran si el objeto ya es
	     nulo despues de dormir; este archivo tambien (isNull antes de borrar). Cada cuerpo se programa una sola vez
	     (lista local VIOC_PU_BODY_SEEN; no se marca el cuerpo con setVariable porque sus variables pueden copiarse a la
	     unidad nueva).
	2) ELIMINAR VEHICULO. Parametro de lobby VIOC_PU_VEH_DELETE: 0 = no, 1 = si (por defecto).
	   - Accion de mantener pulsado VIOC_PU_HOLD s (BIS_fnc_holdActionAdd, en Client_AddMissionActions.sqf: se pone al
	     entrar y al reaparecer) sobre el vehiculo que miras (cursorObject), a VIOC_PU_RANGE m o menos y a pie. Al terminar
	     se manda al servidor (remoteExecCall a 2); el servidor comprueba remoteExecutedOwner y lo revisa todo otra vez en
	     el mismo instante en que borra (llamada sin pausas: nadie puede subirse entre la revision y el borrado).
	   - Se puede: coches, camiones, blindados, motos (Car, Tank, Motorcycle), botes (Ship) y helicopteros (Helicopter, sin
	     paracaidas). Helicopteros si: uno comprado se puede quedar volcado o sin combustible en la selva igual que un
	     coche, y las aeronaves de otros sistemas tienen su marca (aerodromos, asalto aereo, apoyo aereo, drones). Aviones
	     no (los manejan los aerodromos: estacionados, servicio, regreso a base). Nunca drones (unitIsUAV) ni estaticas.
	   - Solo si: esta vacio (sin tripulantes vivos), parado (VIOC_PU_MAX_SPEED km/h) y en el suelo o el agua; ningun otro
	     jugador a VIOC_PU_NEAR_PLAYER m; nadie de otro grupo asignado a el subiendose (VIOC_PU_GETIN_R m); no lo tiene
	     asignado un equipo de la IA que siga cerca (conductor, artillero, comandante o carga de otro grupo a menos de
	     VIOC_PU_ASSIGNED_R m; la IA de tu grupo no cuenta); no esta enganchado, remolcado (Advanced Towing:
	     SA_Tow_Ropes / SA_Cargo), con cuerdas (ropeAttachedObjects) ni lleva otro vehiculo cargado (getVehicleCargo);
	     es de tu bando o no es de nadie (cti_net vacio o tu bando; uno del enemigo solo si ya lo usaste: VIOC_PERF_pUse de
	     perf_cleanup, que marca los vehiculos donde estuvo un jugador o su grupo).
	   - Nunca: el HQ de ningun bando ni nada con cti_gc_noremove; estructuras de la base (cti_structure_type,
	     cti_structures, cti_structures_wip); FOB (cti_fobs); defensas de la base (cti_defences, cti_aman_enabled) o de un
	     pueblo (CTI_defense de los ayudantes de cti_town_defenses); vehiculos de otros sistemas en uso (VIOC_PU_VVARS:
	     transportes de ai_transport, aeronaves estacionadas de airfields, asalto aereo, apoyo aereo y Ghostrider, drones a
	     pedido, operaciones especiales, mercenarios, coche bomba de irregular_warfare, refuerzos de la capital, guarnicion
	     y ofensiva de la mision B, nidos de fortifications, ayudantes de forward_bases, airfields y towns_capital, y todo lo
	     que lleve VIOC_KEEP). Los coches civiles estacionados de civ_vehicles (vioc_civ) SI se pueden borrar si estan vacios:
	     son decorado y civ_vehicles los repone cada 25 min en pueblos sin jugadores (se quitan de VIOC_CIV_LIST).
	   - Devolucion: VIOC_PU_REFUND (25 %) del precio de BECTI del vehiculo (missionNamespace getVariable clase, o
	     CTI_CUSTOM_ENTITY_<cti_customid>; CTI_UNIT_PRICE) por (1 - dano), a tus fondos, SOLO si lo compraste tu (variable
	     Owner = tu UID, la pone Client_OnPurchaseOrderReceived.sqf). Si no, sin devolucion y el aviso lo dice.
	   - Listas: BECTI no lleva una lista de los vehiculos del bando; si el vehiculo esta en cti_salvagers (recuperador
	     independiente), en las listas de vehiculos de un pueblo (cti_town_*_active_vehicles) o en VIOC_CIV_LIST, se quita.
	     El guardado de BECTI (Server_SaveToProfile.sqf, "empty_vehicles") toma los vehiculos con allMissionObjects en el
	     momento de guardar: uno borrado ya no existe y no se guarda. Los bucles que vigilan vehiculos (HandleEmptyVehicle,
	     el abandono de perf_cleanup, los marcadores) terminan solos con el objeto nulo.
	   - Aviso al jugador: "Vehiculo eliminado: <nombre>." con la devolucion (o "sin devolucion: ..."), o el motivo.
	Topes: un pedido cada VIOC_PU_COOLDOWN s por jugador (servidor) y cada 2 s (cliente); la condicion de la accion se
	calcula como mucho cada 0,25 s (cursorObject y unas comprobaciones); un hilo dormido por cuerpo (uno por muerte). No crea
	IA ni objetos (salvo la prueba de consola, un vehiculo vacio a la vez) y no guarda nada.
	Consola (LOCAL EXEC; en la partida LAN el anfitrion es servidor y cliente):
	  hint (call VIOC_PU_fnc_info);              estado: parametros, cuerpos programados y borrados, vehiculos borrados
	  hint ([cursorObject] call VIOC_PU_fnc_why);  (anfitrion) si el vehiculo que miras se puede eliminar y por que no
	  [0] call VIOC_PU_fnc_testVeh;               (anfitrion) crea a 8 m un vehiculo vacio de tu fabrica ligera comprado por
	                                              ti (Owner = tu UID): se puede eliminar con devolucion
	  [1] call VIOC_PU_fnc_testVeh;               igual pero con VIOC_KEEP = true (otro sistema lo usa): se rechaza
	  [2] call VIOC_PU_fnc_testVeh;               igual pero sin Owner (no lo compraste): se elimina sin devolucion
	  VIOC_PU_BODY_DELETE = 1;                    (cliente) cambia el tiempo del cuerpo sin volver al lobby (0, 1, 30, 120)
	  hint str (count ((profileNamespace getVariable [format ["SAVE_%1_%2_EMPTYVEHICLES", missionName, worldName], []]) select
	    {((_x select 1) distance2D VIOC_PU_TPOS) < 3}));  (anfitrion, tras el guardado automatico) 0 = el de prueba no quedo guardado
*/
if (!isNil "VIOC_PU_LOADED") exitWith {};
VIOC_PU_LOADED = true;

//--- Ajustes
VIOC_PU_RANGE = 15;               // m: alcance de la accion (cliente)
VIOC_PU_SRV_RANGE = 20;           // m: lo que acepta el servidor (la posicion del jugador llega con algo de retraso)
VIOC_PU_HOLD = 2.5;               // s que hay que mantener pulsado
VIOC_PU_NEAR_PLAYER = 10;         // m: otro jugador tan cerca del vehiculo bloquea el borrado
VIOC_PU_GETIN_R = 8;              // m: alguien de otro grupo asignado al vehiculo tan cerca = se esta subiendo
VIOC_PU_ASSIGNED_R = 300;         // m: un equipo IA asignado al vehiculo a esta distancia todavia lo usa (mas lejos: abandonado)
VIOC_PU_MAX_SPEED = 5;            // km/h: mas rapido = en movimiento
VIOC_PU_MAX_ALT = 3;              // m sobre el suelo o el agua como mucho (helicopteros y vehiculos colgados)
VIOC_PU_TOW_R = 40;               // m: vehiculos que podrian estar remolcandolo
VIOC_PU_REFUND = 0.25;            // parte del precio que se devuelve si lo compraste tu
VIOC_PU_COOLDOWN = 3;             // s entre pedidos del mismo jugador (servidor)
VIOC_PU_BODY_MIN_NOLAST = 300;    // s: espera minima del cuerpo si el equipo puede seguir en el (IA, otra penalizacion)
VIOC_PU_LOOT_R = 10;              // m: con el jugador tan cerca de su cuerpo no se borra (lo esta saqueando)
VIOC_PU_HOLDER_R = 5;             // m: armas tiradas junto al cuerpo que se borran con el (sin perf_cleanup)
VIOC_PU_HOLDER_FREE = 50;         // m sin otros jugadores para borrar esas armas (sin perf_cleanup)
VIOC_PU_ICON = "\a3\ui_f\data\IGUI\Cfg\HoldActions\holdAction_unbind_ca.paa";
//--- variables de otros sistemas que impiden el borrado: [variable, motivo]. Bloquea si existe y no es false ni nula.
VIOC_PU_VVARS = [
	["VIOC_KEEP", "lo esta usando otro sistema de la mision"],
	["VIOC_AF_parked", "es una aeronave estacionada del aerodromo"],
	["vioc_aa", "es del asalto aereo de la IA"],
	["vioc_specops", "es de una operacion especial"],
	["vioc_as_nosave", "es del apoyo aereo"],
	["vioc_as_kind", "es del apoyo aereo"],
	["vioc_grg", "es del Ghostrider"],
	["vioc_uav", "es un dron a pedido"],
	["vioc_merc", "es de los mercenarios"],
	["vioc_iw_vbied", "es un coche bomba"],
	["vioc_cr", "es de los refuerzos de la capital"],
	["vioc_mb_guard", "es de la guarnicion de la mision"],
	["vioc_mb_wave", "es de la ofensiva de la mision"],
	["vioc_at_owner", "es el transporte de un equipo de la IA"],
	["vioc_fort", "es una fortificacion"],
	["vioc_fb_town", "es un ayudante de la base avanzada"],
	["vioc_tc_def", "es una defensa de la capital"],
	["vioc_af_def", "es una defensa del aerodromo"]
];

//--- Estado (antes de las funciones: init.sqf es programado y la condicion de la accion puede evaluarse a mitad de esta carga)
if (isServer) then {
	VIOC_PU_LASTREQ = createHashMap;
	VIOC_PU_VEH_DONE = 0;
	VIOC_PU_VEH_REFUSED = 0;
	VIOC_PU_REFUNDED = 0;
};
if (hasInterface) then {
	VIOC_PU_BODY_SEEN = [];
	VIOC_PU_BODY_PEND = 0;
	VIOC_PU_BODY_DONE = 0;
	VIOC_PU_AV = false;
	VIOC_PU_AV_T = 0;
	VIOC_PU_TGT = objNull;
	VIOC_PU_HOLD_TGT = objNull;
	VIOC_PU_SENT_T = -100;
};

//--- parametros de lobby (sin lobby o con un valor raro: el de por defecto)
{
	_x params ["_var", "_def", "_ok"];
	private _v = missionNamespace getVariable [_var, _def];
	if !(_v isEqualType 0 && {_v in _ok}) then {_v = _def};
	missionNamespace setVariable [_var, _v];
} forEach [["VIOC_PU_BODY_DELETE", 30, [0, 1, 30, 120]], ["VIOC_PU_VEH_DELETE", 1, [0, 1]]];

//--- ---------------------------------- comun ----------------------------------
//--- [vehiculo] -> true si es de un tipo que la accion acepta (vivo; coche, blindado, moto, bote o helicoptero; no dron ni estatica)
VIOC_PU_fnc_isVehType = {
	params [["_v", objNull, [objNull]]];
	!isNull _v && {alive _v}
	&& {(_v isKindOf "Car") || {_v isKindOf "Tank"} || {_v isKindOf "Motorcycle"} || {_v isKindOf "Ship"} || {(_v isKindOf "Helicopter") && {!(_v isKindOf "ParachuteBase")}}}
	&& {!(_v isKindOf "StaticWeapon")}
	&& {!(unitIsUAV _v)}
};

//--- [cuerpo] -> true si lo borro (solo el cuerpo; dentro de un vehiculo, el vehiculo no se toca)
VIOC_PU_fnc_bodyDelete = {
	params [["_b", objNull, [objNull]]];
	if (isNull _b || {alive _b}) exitWith {false};
	if (isNull objectParent _b) then {
		if (!isNil "VIOC_PERF_fnc_bodyHolders") then {[_b] call VIOC_PERF_fnc_bodyHolders} else {[_b] call VIOC_PU_fnc_holders};
		deleteVehicle _b;
	} else {
		[objectParent _b, _b] remoteExecCall ["deleteVehicleCrew", objectParent _b]; //--- donde el vehiculo es local (wiki)
	};
	true
};

//--- [cuerpo]: sin perf_cleanup, borra las armas tiradas a VIOC_PU_HOLDER_R m si no hay otro jugador vivo a VIOC_PU_HOLDER_FREE m
VIOC_PU_fnc_holders = {
	params [["_b", objNull, [objNull]]];
	if (isNull _b) exitWith {};
	if ((allPlayers findIf {alive _x && {(_x distance _b) < VIOC_PU_HOLDER_FREE}}) > -1) exitWith {};
	{
		if !(_x getVariable ["VIOC_KEEP", false]) then {deleteVehicle _x};
	} forEach (nearestObjects [_b, ["WeaponHolderSimulated"], VIOC_PU_HOLDER_R]);
};

//--- [vehiculo] -> precio de BECTI (sin tripulacion) o -1 si no se conoce
VIOC_PU_fnc_price = {
	params [["_v", objNull, [objNull]]];
	if (isNull _v) exitWith {-1};
	private _vn = typeOf _v;
	private _cid = _v getVariable "cti_customid";
	if (!isNil "_cid") then {
		private _cn = missionNamespace getVariable [format ["CTI_CUSTOM_ENTITY_%1", _cid], ""];
		if (_cn isEqualType "" && {_cn != ""}) then {_vn = _cn};
	};
	private _info = missionNamespace getVariable [_vn, []];
	private _idx = missionNamespace getVariable ["CTI_UNIT_PRICE", 2];
	if (_info isEqualType [] && {(count _info) > _idx} && {(_info select _idx) isEqualType 0}) then {_info select _idx} else {-1}
};

//--- [motivo de VIOC_PU_VVARS presente en el vehiculo o ""]
VIOC_PU_fnc_sysVar = {
	params ["_v"];
	private _why = "";
	{
		_x params ["_var", "_txt"];
		private _val = _v getVariable _var;
		if (!isNil "_val" && {!(_val isEqualTo false)} && {!((_val isEqualType objNull) && {isNull _val})} && {!((_val isEqualType grpNull) && {isNull _val})}) exitWith {_why = _txt};
	} forEach VIOC_PU_VVARS;
	_why
};

//--- ---------------------------------- cliente: cuerpo ----------------------------------
//--- Evento Respawn del jugador: [unidad nueva, cuerpo]
VIOC_PU_fnc_onRespawn = {
	params [["_unit", objNull], ["_corpse", objNull]];
	if (!hasInterface || {!(_corpse isEqualType objNull)} || {isNull _corpse} || {_corpse isEqualTo _unit}) exitWith {};
	if (alive _corpse || {!(_corpse isKindOf "CAManBase")}) exitWith {};
	private _d = missionNamespace getVariable ["VIOC_PU_BODY_DELETE", 30];
	if (!(_d isEqualType 0) || {_d <= 0}) exitWith {};
	if (_corpse in VIOC_PU_BODY_SEEN) exitWith {};
	VIOC_PU_BODY_SEEN pushBack _corpse;
	private _wait = if (_d == 1) then {0.5} else {_d};
	if ((missionNamespace getVariable ["CTI_RESPAWN_PENALTY", -1]) != -1) then {_wait = _wait max VIOC_PU_BODY_MIN_NOLAST};
	VIOC_PU_BODY_PEND = VIOC_PU_BODY_PEND + 1;
	[_corpse, _wait, (units group _unit) select {!isPlayer _x && {alive _x}}] spawn VIOC_PU_fnc_bodyLater;
};

//--- [cuerpo, espera, IA del grupo al reaparecer] (hilo propio: espera el fin del menu, duerme y borra; si otro lo borro antes,
//--- no hace nada)
VIOC_PU_fnc_bodyLater = {
	params ["_b", "_wait", ["_ais", []]];
	private _t0 = time;
	waitUntil {sleep 0.5; isNull _b || {!(missionNamespace getVariable ["CTI_P_Respawning", false])} || {(time - _t0) > 300}};
	if (!isNull _b && {((uniform player) != (uniform _b)) || {(vest player) != (vest _b)} || {(backpack player) != (backpack _b)}}) then {_wait = _wait max VIOC_PU_BODY_MIN_NOLAST};
	if ((_ais findIf {isNull _x}) > -1) then {_wait = _wait max VIOC_PU_BODY_MIN_NOLAST}; //--- reapareciste en una IA (BECTI la borra)
	sleep _wait;
	private _n = 0;
	while {!isNull _b && {alive player} && {(player distance _b) < VIOC_PU_LOOT_R} && {_n < 30}} do {sleep 10; _n = _n + 1};
	VIOC_PU_BODY_PEND = (VIOC_PU_BODY_PEND - 1) max 0;
	if ([_b] call VIOC_PU_fnc_bodyDelete) then {VIOC_PU_BODY_DONE = VIOC_PU_BODY_DONE + 1};
	VIOC_PU_BODY_SEEN = VIOC_PU_BODY_SEEN select {!isNull _x};
};

//--- Pone el evento Respawn una vez (sigue en la unidad nueva tras cada reaparicion)
VIOC_PU_fnc_clientInit = {
	if (!hasInterface) exitWith {};
	waitUntil {sleep 1; !isNull player && {!isNil "CTI_InitClient"}};
	if (isNil "VIOC_PU_REH") then {
		VIOC_PU_REH = player addEventHandler ["Respawn", {_this call VIOC_PU_fnc_onRespawn}];
	};
};

//--- ---------------------------------- cliente: accion ELIMINAR VEHICULO ----------------------------------
//--- condicion de la accion (la evalua el motor; el resultado se guarda 0,25 s)
VIOC_PU_fnc_vehAvail = {
	if (diag_tickTime < VIOC_PU_AV_T) exitWith {VIOC_PU_AV};
	VIOC_PU_AV_T = diag_tickTime + 0.25;
	private _v = cursorObject;
	VIOC_PU_AV = ((missionNamespace getVariable ["VIOC_PU_VEH_DELETE", 1]) > 0)
		&& {alive player} && {isNull objectParent player} && {!visibleMap}
		&& {!(missionNamespace getVariable ["CTI_P_PreBuilding", false])}
		&& {[_v] call VIOC_PU_fnc_isVehType}
		&& {(player distance _v) <= VIOC_PU_RANGE}
		&& {((crew _v) findIf {alive _x}) < 0}
		&& {isNil {_v getVariable "cti_structure_type"}}
		&& {!(_v isEqualTo ((missionNamespace getVariable ["CTI_P_SideLogic", objNull]) getVariable ["cti_hq", objNull]))};
	VIOC_PU_TGT = if (VIOC_PU_AV) then {_v} else {objNull};
	VIOC_PU_AV
};

//--- al empezar a mantener pulsado: se fija el vehiculo
VIOC_PU_fnc_vehStart = {
	VIOC_PU_HOLD_TGT = VIOC_PU_TGT;
	if (!isNull VIOC_PU_HOLD_TGT) then {hintSilent format ["ELIMINAR VEHICULO: %1 (suelta la tecla para cancelar)", getText (configFile >> "CfgVehicles" >> (typeOf VIOC_PU_HOLD_TGT) >> "displayName")]};
};

//--- mientras se mantiene pulsado: sigue cerca, a pie y el vehiculo vacio
VIOC_PU_fnc_vehHold = {
	private _v = VIOC_PU_HOLD_TGT;
	!isNull _v && {alive _v} && {alive player} && {isNull objectParent player}
	&& {(player distance _v) <= (VIOC_PU_RANGE + 1)} && {((crew _v) findIf {alive _x}) < 0}
};

//--- al completar: pedido al servidor
VIOC_PU_fnc_vehDone = {
	private _v = VIOC_PU_HOLD_TGT;
	VIOC_PU_HOLD_TGT = objNull;
	if (isNull _v) exitWith {};
	if ((diag_tickTime - VIOC_PU_SENT_T) < 2) exitWith {};
	VIOC_PU_SENT_T = diag_tickTime;
	[player, _v] remoteExecCall ["VIOC_PU_fnc_vehRequest", 2];
};

//--- [ok, texto]: respuesta del servidor
VIOC_PU_fnc_reply = {
	params [["_ok", false], ["_text", ""]];
	if (!hasInterface || {!(_text isEqualType "")} || {_text == ""}) exitWith {};
	systemChat _text;
	hintSilent _text;
};

//--- ---------------------------------- servidor: ELIMINAR VEHICULO ----------------------------------
//--- Pedido de un jugador (remoteExecCall desde su cliente; sin pausas hasta el borrado)
VIOC_PU_fnc_vehRequest = {
	params [["_player", objNull, [objNull]], ["_veh", objNull, [objNull]]];
	if (!isServer || {isNull _player}) exitWith {};
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != (owner _player)}) exitWith {diag_log format ["[VIOC player_utils] pedido ignorado: la maquina %1 no controla a %2", _ro, name _player]};
	private _uid = getPlayerUID _player;
	private _key = if (_uid == "") then {str _player} else {_uid};
	if ((time - (VIOC_PU_LASTREQ getOrDefault [_key, -1000])) < VIOC_PU_COOLDOWN) exitWith {
		[_player, false, "ELIMINAR VEHICULO: espera unos segundos entre pedidos."] call VIOC_PU_fnc_send;
	};
	VIOC_PU_LASTREQ set [_key, time];
	private _why = [_player, _veh] call VIOC_PU_fnc_vehWhy;
	if (_why != "") exitWith {
		VIOC_PU_VEH_REFUSED = VIOC_PU_VEH_REFUSED + 1;
		[_player, false, format ["No se puede eliminar el vehiculo: %1.", _why]] call VIOC_PU_fnc_send;
		diag_log format ["[VIOC player_utils] %1 no pudo eliminar %2: %3", name _player, typeOf _veh, _why];
	};
	private _txt = [_player, _veh] call VIOC_PU_fnc_vehDelete;
	[_player, true, _txt] call VIOC_PU_fnc_send;
};

VIOC_PU_fnc_send = {
	params ["_player", "_ok", "_text"];
	if (isNull _player) exitWith {};
	[_ok, _text] remoteExecCall ["VIOC_PU_fnc_reply", _player];
};

//--- [vehiculo, logicas de bando] -> true si es una defensa de la base (cti_defences: objetos o [objeto, ...])
VIOC_PU_fnc_isBaseDefense = {
	params ["_veh", "_logics"];
	private _hit = false;
	{
		private _l = _x getVariable ["cti_defences", []];
		if (_l isEqualType [] && {(_l findIf {(_x isEqualTo _veh) || {(_x isEqualType []) && {(count _x) > 0} && {(_x select 0) isEqualTo _veh}}}) > -1}) exitWith {_hit = true};
	} forEach _logics;
	_hit
};

//--- [vehiculo] -> true si es la estatica de un ayudante de defensa de algun pueblo (CTI_defense de cti_town_defenses)
VIOC_PU_fnc_isTownDefense = {
	params ["_veh"];
	private _hit = false;
	{
		private _l = _x getVariable ["cti_town_defenses", []];
		if (_l isEqualType [] && {(_l findIf {!isNull _x && {(_x getVariable ["CTI_defense", objNull]) isEqualTo _veh}}) > -1}) exitWith {_hit = true};
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	_hit
};

//--- [vehiculo] -> true si otro vehiculo cercano lo lleva de una cuerda (ropeAttachedObjects; Advanced Towing ata la cuerda a
//--- un ayudante enganchado al remolcado, con SA_Cargo = el remolcado)
VIOC_PU_fnc_isTowed = {
	params ["_veh"];
	private _hit = false;
	{
		if !(_x isEqualTo _veh) then {
			private _r = ropeAttachedObjects _x;
			if ((_r findIf {(_x isEqualTo _veh) || {(_x getVariable ["SA_Cargo", objNull]) isEqualTo _veh}}) > -1) exitWith {_hit = true};
		};
		if (_hit) exitWith {};
	} forEach (_veh nearEntities [["LandVehicle", "Air", "Ship"], VIOC_PU_TOW_R]);
	_hit
};

//--- [jugador, vehiculo] -> "" si se puede eliminar; si no, el motivo (texto para el jugador)
VIOC_PU_fnc_vehWhy = {
	params [["_player", objNull, [objNull]], ["_veh", objNull, [objNull]]];
	if ((missionNamespace getVariable ["VIOC_PU_VEH_DELETE", 1]) <= 0) exitWith {"la accion esta desactivada en el lobby"};
	if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {"la partida termino"};
	if (isNull _player || {!alive _player}) exitWith {"tienes que estar vivo"};
	if (!isNull objectParent _player) exitWith {"tienes que estar a pie"};
	private _side = side group _player;
	if !(_side in [west, east]) exitWith {"tu bando no puede usar esta accion"};
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	if (isNull _veh) exitWith {"no hay ningun vehiculo"};
	if (!alive _veh) exitWith {"esta destruido (la mision limpia los restos sola)"};
	if !([_veh] call VIOC_PU_fnc_isVehType) exitWith {"solo coches, camiones, blindados, motos, botes y helicopteros (no aviones, drones, paracaidas ni estaticas)"};
	if ((_player distance _veh) > VIOC_PU_SRV_RANGE) exitWith {format ["acercate a %1 m o menos", VIOC_PU_RANGE]};
	if (((crew _veh) findIf {alive _x}) > -1) exitWith {"tiene tripulantes"};
	if ((allPlayers findIf {alive _x && {!(_x isEqualTo _player)} && {(_x distance _veh) < VIOC_PU_NEAR_PLAYER}}) > -1) exitWith {format ["hay otro jugador a menos de %1 m", VIOC_PU_NEAR_PLAYER]};
	if (((_veh nearEntities [["CAManBase"], VIOC_PU_GETIN_R]) findIf {alive _x && {!((group _x) isEqualTo (group _player))} && {(assignedVehicle _x) isEqualTo _veh}}) > -1) exitWith {"alguien se esta subiendo"};
	if ((abs (speed _veh)) > VIOC_PU_MAX_SPEED) exitWith {"esta en movimiento"};
	if (((getPos _veh) select 2) > VIOC_PU_MAX_ALT) exitWith {"no esta en el suelo"};
	//--- BECTI: HQ, estructuras, FOB y defensas
	private _logics = [missionNamespace getVariable ["CTI_WEST", objNull], missionNamespace getVariable ["CTI_EAST", objNull]] select {!isNull _x};
	if ((_logics findIf {(_x getVariable ["cti_hq", objNull]) isEqualTo _veh}) > -1) exitWith {"es el HQ"};
	if (!isNil {_veh getVariable "cti_gc_noremove"}) exitWith {"la mision no deja borrarlo (HQ)"};
	if (isNil {_veh getVariable "Owner"} && {(typeOf _veh) in [missionNamespace getVariable ["CTI_WEST_HQ", ""], missionNamespace getVariable ["CTI_EAST_HQ", ""]]}) exitWith {"puede ser el HQ"}; //--- HQ nuevo antes de tener cti_hq (replegar o reparar)
	if (!isNil {_veh getVariable "cti_structure_type"}) exitWith {"es una estructura de la base"};
	if ((_logics findIf {(_veh in (_x getVariable ["cti_structures", []])) || {_veh in (_x getVariable ["cti_structures_wip", []])}}) > -1) exitWith {"es una estructura de la base"};
	if ((_logics findIf {_veh in (_x getVariable ["cti_fobs", []])}) > -1) exitWith {"es una FOB"};
	if (!isNil {_veh getVariable "cti_aman_enabled"}) exitWith {"es una defensa de la base"};
	if ([_veh, _logics] call VIOC_PU_fnc_isBaseDefense) exitWith {"es una defensa de la base"};
	if ([_veh] call VIOC_PU_fnc_isTownDefense) exitWith {"es una defensa de un pueblo"};
	//--- otros sistemas
	private _sys = [_veh] call VIOC_PU_fnc_sysVar;
	if (_sys != "") exitWith {_sys};
	private _asg = ([assignedDriver _veh, assignedGunner _veh, assignedCommander _veh] + (assignedCargo _veh)) select {!isNull _x && {alive _x} && {!isPlayer _x} && {!((group _x) isEqualTo (group _player))} && {(_x distance _veh) < VIOC_PU_ASSIGNED_R}};
	if ((count _asg) > 0) exitWith {format ["lo tiene asignado un equipo de la IA que esta a menos de %1 m", VIOC_PU_ASSIGNED_R]};
	//--- enganches, remolque y carga
	if (!isNull (attachedTo _veh)) exitWith {"esta enganchado a otro objeto"};
	if (((attachedObjects _veh) findIf {!isNull _x && {(_x isKindOf "AllVehicles") || {!isNull (_x getVariable ["SA_Cargo", objNull])}}}) > -1) exitWith {"lleva algo enganchado o lo estan remolcando"};
	if (((count (getVehicleCargo _veh)) > 0) || {(count (ropeAttachedObjects _veh)) > 0} || {(count (_veh getVariable ["SA_Tow_Ropes", []])) > 0}) exitWith {"lleva otro vehiculo, cuerdas o carga colgada"};
	if ([_veh] call VIOC_PU_fnc_isTowed) exitWith {"lo esta remolcando otro vehiculo"};
	//--- lo compro otro jugador que sigue en la partida (Owner = UID del jefe del grupo comprador)
	private _own = _veh getVariable ["Owner", ""];
	if ((_own isEqualType "") && {!(_own in ["", "0", getPlayerUID _player, getPlayerUID (leader group _player)])} && {(allPlayers findIf {(getPlayerUID _x) isEqualTo _own}) > -1}) exitWith {"lo compro otro jugador que sigue en la partida"};
	//--- bando: de nadie, tuyo, o del enemigo pero ya capturado (lo uso un jugador o su grupo; si ese bando tiene jugadores, no:
	//--- VIOC_PERF_pUse lo pone el uso de cualquier jugador)
	private _net = _veh getVariable ["cti_net", -1];
	if ((_net isEqualType 0) && {_net >= 0} && {_net != _sid} && {isNil {_veh getVariable "VIOC_PERF_pUse"} || {(allPlayers findIf {(side group _x) isEqualTo ((_net) call CTI_CO_FNC_GetSideFromID)}) > -1}}) exitWith {"es del enemigo (subete un momento para capturarlo, o destruyelo)"};
	""
};

//--- [jugador, vehiculo] -> borra (ya revisado, sin pausas) y devuelve el aviso
VIOC_PU_fnc_vehDelete = {
	params ["_player", "_veh"];
	private _name = getText (configFile >> "CfgVehicles" >> (typeOf _veh) >> "displayName");
	if (_name == "") then {_name = typeOf _veh};
	private _side = side group _player;
	private _uid = getPlayerUID _player;
	private _owner = _veh getVariable ["Owner", ""];
	private _price = [_veh] call VIOC_PU_fnc_price;
	private _refund = 0;
	private _noRef = "";
	if (!(_owner isEqualType "") || {_owner in ["", "0"]} || {_owner != _uid}) then {
		_noRef = "no lo compraste tu";
	} else {
		if (_price <= 0) then {_noRef = "no se conoce su precio"} else {_refund = round ((_price * VIOC_PU_REFUND * (1 - (damage _veh))) max 0)};
	};
	//--- listas de BECTI y de civ_vehicles (BECTI no lleva otra lista de vehiculos del bando)
	{
		private _l = _x getVariable ["cti_salvagers", []];
		if (_l isEqualType [] && {_veh in _l}) then {_x setVariable ["cti_salvagers", _l - [_veh, objNull], true]};
	} forEach ([missionNamespace getVariable ["CTI_WEST", objNull], missionNamespace getVariable ["CTI_EAST", objNull]] select {!isNull _x});
	{
		private _t = _x;
		{
			private _l = _t getVariable [_x, []];
			if (_l isEqualType [] && {_veh in _l}) then {_t setVariable [_x, _l - [_veh]]};
		} forEach ["cti_town_occupation_active_vehicles", "cti_town_resistance_active_vehicles"];
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	if (!isNil "VIOC_CIV_LIST") then {VIOC_CIV_LIST = VIOC_CIV_LIST - [_veh]};
	//--- muertos que sigan dentro y el vehiculo
	{ if (!alive _x) then {if (local _veh) then {_veh deleteVehicleCrew _x} else {[_veh, _x] remoteExecCall ["deleteVehicleCrew", _veh]}} } forEach (crew _veh); //--- wiki: tripulantes con deleteVehicleCrew
	deleteVehicle _veh;
	if (_refund > 0) then {[group _player, _side, _refund] call CTI_CO_FNC_ChangeFunds};
	VIOC_PU_VEH_DONE = VIOC_PU_VEH_DONE + 1;
	VIOC_PU_REFUNDED = VIOC_PU_REFUNDED + _refund;
	diag_log format ["[VIOC player_utils] %1 elimino %2 (%3); devolucion %4", name _player, _name, typeOf _veh, _refund];
	if (_refund > 0) then {
		format ["Vehiculo eliminado: %1. Te devolvimos $%2 (el %3 por ciento de su precio).", _name, _refund, round (VIOC_PU_REFUND * 100)]
	} else {
		format ["Vehiculo eliminado: %1 (sin devolucion: %2).", _name, _noRef]
	}
};

