//--- (anfitrion) [modo]: un vehiculo vacio de tu fabrica ligera a 8 m (uno a la vez). 0 = comprado por ti, 1 = con VIOC_KEEP, 2 = sin Owner
VIOC_PU_fnc_testVeh = {
	params [["_mode", 0, [0]]];
	if (!isServer || {!hasInterface}) exitWith {hint "VIOC player_utils: la prueba es para el anfitrion (LOCAL EXEC)"};
	if (!isNil "VIOC_PU_TESTV" && {!isNull VIOC_PU_TESTV} && {({alive _x} count (crew VIOC_PU_TESTV)) == 0}) then {deleteVehicle VIOC_PU_TESTV};
	private _list = missionNamespace getVariable [format ["CTI_%1_%2Units", side group player, missionNamespace getVariable ["CTI_LIGHT", "Light"]], []];
	private _cls = "";
	{
		if (_x isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _x)} && {(_x isKindOf "Car") || {_x isKindOf "Tank"}}) exitWith {_cls = _x};
	} forEach _list;
	if (_cls == "") exitWith {hint "VIOC player_utils: no encontre un vehiculo en la lista de tu fabrica ligera"};
	private _pos = player getPos [8, getDir player];
	VIOC_PU_TESTV = createVehicle [_cls, _pos, [], 0, "NONE"];
	VIOC_PU_TESTV setDir (getDir player);
	VIOC_PU_TPOS = getPosATL VIOC_PU_TESTV; //--- para mirar despues que no quedo en el guardado de BECTI
	VIOC_PU_TESTV setVariable ["cti_net", (side group player) call CTI_CO_FNC_GetSideID, true];
	if (_mode != 2) then {VIOC_PU_TESTV setVariable ["Owner", getPlayerUID player, true]};
	if (_mode == 1) then {VIOC_PU_TESTV setVariable ["VIOC_KEEP", true]};
	hint format ["VIOC player_utils: %1 vacio a 8 m (modo %2, precio BECTI %3). Miralo y manten pulsado ELIMINAR VEHICULO.", _cls, _mode, [VIOC_PU_TESTV] call VIOC_PU_fnc_price];
	VIOC_PU_TESTV
};

